import{_ as e,c as a,a2 as r,o as i}from"./chunks/framework.CO0qOYmW.js";const p=JSON.parse('{"title":"安全与合规治理概述","description":"","frontmatter":{},"headers":[],"relativePath":"ai/09-security-governance/01-security/01-overview.md","filePath":"ai/09-security-governance/01-security/01-overview.md","lastUpdated":1783608971000}'),o={name:"ai/09-security-governance/01-security/01-overview.md"};function d(l,t,n,s,c,h){return i(),a("div",null,t[0]||(t[0]=[r('<h1 id="安全与合规治理概述" tabindex="-1">安全与合规治理概述 <a class="header-anchor" href="#安全与合规治理概述" aria-label="Permalink to &quot;安全与合规治理概述&quot;">​</a></h1><p>安全与合规治理关注 AI 应用在企业环境中的数据安全、访问控制、内容审核、模型准入和审计留痕。AI 应用会接触用户输入、企业知识、工具调用和模型输出，因此必须从设计阶段就纳入安全边界。</p><h2 id="核心定位" tabindex="-1">核心定位 <a class="header-anchor" href="#核心定位" aria-label="Permalink to &quot;核心定位&quot;">​</a></h2><ul><li><strong>防止输入攻击</strong>：识别 Prompt 注入、越权请求和恶意上下文污染。</li><li><strong>保护企业数据</strong>：控制敏感信息、权限隔离、数据留存和外部模型调用边界。</li><li><strong>治理模型输出</strong>：对内容安全、工具调用、风险响应和审计追踪建立机制。</li></ul><h2 id="治理范围" tabindex="-1">治理范围 <a class="header-anchor" href="#治理范围" aria-label="Permalink to &quot;治理范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>范围</th><th>说明</th></tr></thead><tbody><tr><td>输入安全</td><td>Prompt 注入、越权访问、敏感信息和恶意文件输入</td></tr><tr><td>输出治理</td><td>内容审核、风险拦截、敏感内容处理和工具调用审批</td></tr><tr><td>合规治理</td><td>数据合规、模型准入、权限策略、审计留痕和保留周期</td></tr><tr><td>运行控制</td><td>结合日志、告警和审批机制处理高风险请求</td></tr></tbody></table><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>先理解 AI 应用常见安全风险，尤其是 Prompt 注入和数据泄露。</li><li>再建立输入、输出和工具调用的安全控制点。</li><li>最后从企业合规角度设计模型准入、权限策略和审计机制。</li></ol>',8)]))}const m=e(o,[["render",d]]);export{p as __pageData,m as default};
